extern void ARNAUD_dnaupd(ar_state *state, double *resid, double *v, int ldv,
                          int *ipntr, double *workd, double *workl);

static inline void csr_mv(int n, const int *indptr, const int *indices,
                          const double *data, const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        int a = indptr[i];
        int b = indptr[i + 1];
        for (int j = a; j < b; j++) {
            s += data[j] * x[indices[j]];
        }
        y[i] = s;
    }
}

/* Returns info. Fills nconv_out, iter_out. */
int eigs_iterate(int n, int k, int ncv, int maxiter, double tol,
                 const int *indptr, const int *indices, const double *data,
                 double *resid, double *v, double *workd, double *workl, int *ipntr,
                 int *nconv_out, int *iter_out) {
    ar_state st;
    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.ido = 0;
    st.info = 1;
    st.which = 0; /* LM */
    st.bmat = 0;  /* I */
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    int guard = 0;
    int guard_max = maxiter * (ncv + 2) + 1000;
    while (1) {
        ARNAUD_dnaupd(&st, resid, v, n, ipntr, workd, workl);
        int ido = st.ido;
        if (ido == 1 || ido == -1 || ido == 5) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            csr_mv(n, indptr, indices, data, workd + x0, workd + y0);
        } else if (ido == 2) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            memcpy(workd + y0, workd + x0, (size_t)n * sizeof(double));
        } else if (ido == 4) {
            /* should not happen with info=1 start; fill resid with ones */
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else {
            break;
        }
        if (++guard > guard_max) {
            st.info = 1;
            break;
        }
    }
    *nconv_out = st.nconv;
    *iter_out = st.iter;
    return st.info;
}
