#include <string.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    double tol;
    double getv0_rnorm0;
    double aitr_betaj;
    double aitr_rnorm1;
    double aitr_wnorm;
    double aup2_rnorm;
    int which;
    int ido;
    int info;
    int bmat;
    int mode;
    int n;
    int ncv;
    int nev;
    int shift;
    int maxiter;
    int nconv;
    int iter;
    int np;
    unsigned char pad[256];
} ar_state;

extern void ARNAUD_dnaupd(ar_state *state, double *resid, double *v, int ldv,
                          int *ipntr, double *workd, double *workl);

/*
 * Best-effort signature from the wrapper:
 * rdi=state, esi=rvec, edx=howmny, rcx=sselect, r8=dr, r9=di,
 * xmm0=sigmar, xmm1=sigmai,
 * stack (rtl push order, so first stack arg is last pushed):
 *   push r15, rbx, (-0xd0), r14, r13, (-0xb0), (-0xc0), r12, (-0xc8)
 * After call, rsp+8 is return, so stack args at +8,+16,... are:
 *   +8  = last pushed = -0xc8  (ldz from zr.shape[0])
 *   +16 = r12
 *   +24 = -0xc0
 *   +32 = -0xb0
 *   +40 = r13
 *   +48 = r14
 *   +56 = -0xd0
 *   +64 = rbx
 *   +72 = r15
 *
 * Python arg order: state, rvec, howmny, sselect, dr, di, zr, sigmar, sigmai,
 *                   workev, resid, v, ipntr, workd, workl
 * Hidden ldv/ldz are inserted by the wrapper from array shapes.
 *
 * Try the natural ARPACK dneupd order with hidden leading dims:
 * (state, rvec, howmny, sselect, dr, di, zr, ldz, sigmar, sigmai,
 *  workev, resid, v, ldv, ipntr, workd, workl)
 * That is 6 reg + 2 xmm + 9 stack. We have 9 stack pushes. Good.
 * Mapping if that order:
 * rcx=sselect, r8=dr, r9=di  (matches register setup if -0xb8=sselect, -0xa8=dr, -0xa0=di)
 * stack +8 = ldz = -0xc8. Wrapper sets -0xc8 from 0x20 of the array at -0x68, i.e. a shape dim. Plausible ldz.
 */
extern void ARNAUD_dneupd(ar_state *state, int rvec, int howmny, int *sselect,
                          double *dr, double *di, double *z, int ldz,
                          double sigmar, double sigmai, double *workev,
                          double *resid, double *v, int ldv, int *ipntr,
                          double *workd, double *workl);

static inline void csr_mv(int n, const int *indptr, const int *indices,
                          const double *data, const double *x, double *y) {
    for (int i = 0; i < n; ++i) {
        double s = 0.0;
        int a = indptr[i];
        int b = indptr[i + 1];
        for (int j = a; j < b; ++j)
            s += data[j] * x[indices[j]];
        y[i] = s;
    }
}

int eigs_solve(int n, int k, int ncv, int maxiter, double tol,
               const int *indptr, const int *indices, const double *data,
               const double *v0,
               double *dr, double *di, double *z,
               int *info_out) {
    ar_state st;
    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.ido = 0;
    st.info = 1;
    st.which = 0;
    st.bmat = 0;
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    double *resid = (double *)malloc((size_t)n * sizeof(double));
    double *v = (double *)malloc((size_t)n * (size_t)ncv * sizeof(double));
    double *workd = (double *)malloc((size_t)3 * n * sizeof(double));
    double *workl = (double *)malloc((size_t)3 * ncv * (ncv + 2) * sizeof(double));
    int *ipntr = (int *)calloc(14, sizeof(int));
    int *sselect = (int *)calloc((size_t)ncv, sizeof(int));
    double *workev = (double *)calloc((size_t)3 * ncv, sizeof(double));
    if (!resid || !v || !workd || !workl || !ipntr || !sselect || !workev) {
        *info_out = -999;
        free(resid); free(v); free(workd); free(workl); free(ipntr); free(sselect); free(workev);
        return -999;
    }
    memcpy(resid, v0, (size_t)n * sizeof(double));
    memset(v, 0, (size_t)n * (size_t)ncv * sizeof(double));
    memset(workd, 0, (size_t)3 * n * sizeof(double));
    memset(workl, 0, (size_t)3 * ncv * (ncv + 2) * sizeof(double));

    int guard = 0;
    int guard_max = maxiter * (ncv + 2) + 1000;
    while (1) {
        ARNAUD_dnaupd(&st, resid, v, n, ipntr, workd, workl);
        int ido = st.ido;
        if (ido == 1 || ido == -1 || ido == 5) {
            csr_mv(n, indptr, indices, data, workd + ipntr[0], workd + ipntr[1]);
        } else if (ido == 2) {
            memcpy(workd + ipntr[1], workd + ipntr[0], (size_t)n * sizeof(double));
        } else if (ido == 4) {
            for (int i = 0; i < n; ++i) resid[i] = 1.0;
        } else {
            break;
        }
        if (++guard > guard_max) {
            st.info = 1;
            break;
        }
    }
    int info = st.info;
    st.info = 0;
    memset(dr, 0, (size_t)(k + 1) * sizeof(double));
    memset(di, 0, (size_t)(k + 1) * sizeof(double));
    memset(z, 0, (size_t)n * (size_t)(k + 1) * sizeof(double));
    ARNAUD_dneupd(&st, 1, 0, sselect, dr, di, z, n,
                  0.0, 0.0, workev, resid, v, n, ipntr, workd, workl);
    *info_out = st.info;
    int nconv = st.nconv;
    free(resid); free(v); free(workd); free(workl); free(ipntr); free(sselect); free(workev);
    (void)info;
    return nconv;
}
