#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#ifdef _OPENMP
#include <omp.h>
#endif

static void mv_scalar(int n, const int *indptr, const int *indices, const double *data,
                      const double *x, double *y) {
    for (int i = 0; i < n; ++i) {
        double s = 0.0;
        int a = indptr[i], b = indptr[i+1];
        for (int j = a; j < b; ++j) s += data[j] * x[indices[j]];
        y[i] = s;
    }
}

static void mv_omp(int n, const int *indptr, const int *indices, const double *data,
                   const double *x, double *y) {
#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
    for (int i = 0; i < n; ++i) {
        double s = 0.0;
        int a = indptr[i], b = indptr[i+1];
        for (int j = a; j < b; ++j) s += data[j] * x[indices[j]];
        y[i] = s;
    }
}

/* 4-row unroll with manual remainder */
static void mv_unroll(int n, const int *indptr, const int *indices, const double *data,
                      const double *x, double *y) {
    int i = 0;
    for (; i + 3 < n; i += 4) {
        for (int r = 0; r < 4; ++r) {
            double s = 0.0;
            int a = indptr[i+r], b = indptr[i+r+1];
            int j = a;
            for (; j + 3 < b; j += 4) {
                s += data[j] * x[indices[j]];
                s += data[j+1] * x[indices[j+1]];
                s += data[j+2] * x[indices[j+2]];
                s += data[j+3] * x[indices[j+3]];
            }
            for (; j < b; ++j) s += data[j] * x[indices[j]];
            y[i+r] = s;
        }
    }
    for (; i < n; ++i) {
        double s = 0.0;
        for (int j = indptr[i]; j < indptr[i+1]; ++j) s += data[j] * x[indices[j]];
        y[i] = s;
    }
}

int main() {
    int n = 1000, nnz = 10000;
    int *indptr = calloc(n+1, sizeof(int));
    int *indices = malloc(nnz * sizeof(int));
    double *data = malloc(nnz * sizeof(double));
    double *x = malloc(n * sizeof(double));
    double *y = malloc(n * sizeof(double));
    srand(1);
    for (int i = 0; i < n; i++) indptr[i] = i * 10;
    indptr[n] = nnz;
    for (int i = 0; i < nnz; i++) { indices[i] = rand() % n; data[i] = (rand()%1000)/100.0; }
    for (int i = 0; i < n; i++) x[i] = 1.0;
    int reps = 20000;
    clock_t t0 = clock();
    for (int r = 0; r < reps; r++) mv_scalar(n, indptr, indices, data, x, y);
    double ts = (double)(clock()-t0)/CLOCKS_PER_SEC;
    t0 = clock();
    for (int r = 0; r < reps; r++) mv_omp(n, indptr, indices, data, x, y);
    double to = (double)(clock()-t0)/CLOCKS_PER_SEC;
    t0 = clock();
    for (int r = 0; r < reps; r++) mv_unroll(n, indptr, indices, data, x, y);
    double tu = (double)(clock()-t0)/CLOCKS_PER_SEC;
    printf("scalar %.3f omp %.3f unroll %.3f y0 %g\n", ts, to, tu, y[0]);
#ifdef _OPENMP
    printf("omp threads max %d\n", omp_get_max_threads());
#endif
    return 0;
}
